@startuml

class Machine {
  + SerialNumber : string
  + Make : string
  + Model : string
  + PurchaseDate : date
}

class Worker {
  + FirstName : string
  + LastName : string
  + BirthDate : date
  + Address : string
  + Skills : string[]
}

class ProductType {
  + Name : string
  + Weight : float
}

class Material {
  + Name : string
}

class Product {
  + Name : string
}

class Client {
  + Name : string
  + Address : string
  + PhoneNumber : string
  + ContactPerson : string
}

class Order {
  + OrderNumber : string
  + OrderDate : date
  + ExpectedDeliveryDate : date
  + ActualDeliveryDate : date
}

class OrderLine {
  + Quantity : int
}

Machine "*" -- "*" Worker : operatedBy
Machine "1" -- "*" ProductType : produces
ProductType "*" -- "1" Material : madeFrom
ProductType "1" -- "*" Product : isType
Client "1" -- "*" Order : issues
Order "1" -- "*" OrderLine : contains
OrderLine "*" -- "1" Product : refersTo

@enduml

